import{_ as a,o as i,c as l,a as t}from"./chunks/framework.Ld7uezS_.js";const m=JSON.parse('{"title":"水系统设备级课程成果概览","description":"","frontmatter":{},"headers":[],"relativePath":"outputs/overview-2026-08-21-water-device-cards.md","filePath":"outputs/overview-2026-08-21-water-device-cards.md","lastUpdated":1787289971000}'),r={name:"outputs/overview-2026-08-21-water-device-cards.md"};function o(d,e,c,s,n,h){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="水系统设备级课程成果概览" tabindex="-1">水系统设备级课程成果概览 <a class="header-anchor" href="#水系统设备级课程成果概览" aria-label="Permalink to &quot;水系统设备级课程成果概览&quot;">​</a></h1><h2 id="本轮目标" tabindex="-1">本轮目标 <a class="header-anchor" href="#本轮目标" aria-label="Permalink to &quot;本轮目标&quot;">​</a></h2><p>按报警系统设备卡的粒度，继续补齐消防给水与自动喷水灭火系统的零基础前置知识，避免把“按方案试水”“观察压力”“确认阀门状态”当成已经学会的步骤。</p><h2 id="本轮完成" tabindex="-1">本轮完成 <a class="header-anchor" href="#本轮完成" aria-label="Permalink to &quot;本轮完成&quot;">​</a></h2><ul><li>在 <code>skill/water-system.md</code> 新增六类设备学习卡： <ol><li>消防水池与高位消防水箱；</li><li>消防主泵、备用泵与稳压泵；</li><li>报警阀组与控制阀；</li><li>水流指示器与压力开关；</li><li>末端试水装置与排水设施；</li><li>水泵接合器、消火栓与喷头。</li></ol></li><li>每类设备统一解释：是什么、由什么组成、怎样工作、正常证据、异常处理和禁止越权动作。</li><li>强化水系统的三类证据：水力证据、机械/设备证据、控制与反馈证据。</li><li>在 <code>training-skill.md</code> 增加水系统六类设备复述清单与统一复述模板，关联 S32-S37、S40、S43、S45、S48。</li><li>同步 <code>standard-mapping.md</code> 的 2.2、3.2、4.2、5.2 映射状态。</li><li>同步 <code>knowledge-coverage-matrix.md</code> 的水系统覆盖状态。</li><li>同步 <code>overview.md</code> 与项目工作日志。</li></ul><h2 id="学习重点" tabindex="-1">学习重点 <a class="header-anchor" href="#学习重点" aria-label="Permalink to &quot;学习重点&quot;">​</a></h2><p>本轮刻意保留以下边界：</p><ul><li>泵在转不等于供水能力合格；</li><li>末端有水不等于报警链和全系统合格；</li><li>阀门位置正确不等于监管反馈正常；</li><li>现场部件动作不等于控制室收到信号；</li><li>具体压力、流量、动作时间、允许误差和维修权限必须按现行依据、设计文件、设备说明书、检测方案和现场授权核验。</li></ul><h2 id="验证与提交" tabindex="-1">验证与提交 <a class="header-anchor" href="#验证与提交" aria-label="Permalink to &quot;验证与提交&quot;">​</a></h2><ul><li>已执行文本最小差异编辑并同步相关课程治理文件。</li><li>后续提交前还需完成：格式检查、训练题号连续性检查、差异复核和本地 Git 提交。</li></ul>',10)])])}const p=a(r,[["render",o]]);export{m as __pageData,p as default};
